def _is_ci_gantt_row(kind: str, output: str) -> bool:
    kind_l = (kind or "").lower()
    bn = Path(output).name.lower() if output else ""
    if kind_l in {"codex-ci", "cursor-ci", "claude-ci", "codex-ci-fix", "cursor-ci-fix", "claude-ci-fix"}:
