    fi
    postplan_rc=$?
    case "$postplan_rc" in
        0)
            set +e
            post_rc=$?
            set -e
            if [[ "$post_rc" -ne 0 ]]; then
                return 31
            fi
            step3_loop_write_phase "$round_num" awaiting-continuation
            return 0
            ;;
        11)
            step3_loop_refresh_issue_from_source_env
            pause_sh="${RUN_STEP3_DESIGN_PAUSE_SAVE_SH:-}"
            if [[ -n "$pause_sh" ]]; then
                if [[ -n "${ISSUE_NUMBER:-}" ]]; then
